import math
from fractions import Fraction

def golden() -> float:
    return (1.0 + math.sqrt(5.0)) / 2.0

def tile_density(alpha: float, n: int) -> float:
    return math.floor(n * alpha) / n

def beatty_word(alpha: float, length: int) -> list[int]:
    return [math.floor((k+1)*alpha) - math.floor(k*alpha) for k in range(length)]

def has_period(word: list[int], p: int) -> bool:
    return all(word[i] == word[i+p] for i in range(len(word)-p))

if __name__ == '__main__':
    phi = golden()
    for n in (10, 100, 1000, 10000, 100000, 1000000):
        r = tile_density(phi, n)
        print(f'N={n:>8} rho={r:.9f} err={abs(r-phi):.2e} bound={1/n:.1e}')
    w = beatty_word(phi, 4000)
    periods = [p for p in range(1, 1000) if has_period(w, p)]
    print('golden periods <1000:', periods or 'NONE (aperiodic)')
    wr = beatty_word(0.6, 4000)
    periods_r = [p for p in range(1, 50) if has_period(wr, p)]
    print('slope 3/5 least period:', min(periods_r))

