function TILE_DENSITY(alpha, N):
    count <- floor(N * alpha)        # cumulative vertical stripes
    rho   <- count / N
    lower <- alpha - 1/N             # proved strict lower bound
    upper <- alpha                   # proved upper bound
    return (rho, lower, upper)

function STEP_WORD(alpha, L):
    return [ floor((n+1)*alpha) - floor(n*alpha)  for n in 0..L-1 ]

function LEAST_PERIOD(w, p_max):
    for p in 1..min(p_max, len(w)//2):
        if w[i] == w[i+p] for all valid i: return p
    return NONE   # aperiodic up to the inspected length

